    private static Result<PayrollOutputFile> File(string name, CsvBuilder csv) => Result<PayrollOutputFile>.Success(new PayrollOutputFile($"payroll-{name.ToLowerInvariant()}.csv", "text/csv; charset=utf-8", csv.ToUtf8Bytes()));

    private async Task<Dictionary<Guid, (decimal Earnings, decimal Tax, decimal Reimbursement, decimal Loan, decimal Variable, decimal Adjustment)>> ComponentTotals(IEnumerable<Guid> ids, CancellationToken ct) { var list = ids.ToList(); return await db.PayrollResultComponents.AsNoTracking().Where(x => x.TenantId == tenant.TenantId && list.Contains(x.PayrollResultId)).GroupBy(x => x.PayrollResultId).ToDictionaryAsync(g => g.Key, g => (g.Where(x => x.IsEarning).Sum(x => x.CalculatedAmount), g.Where(x => x.IsTaxable && x.IsDeduction).Sum(x => x.CalculatedAmount), g.Where(x => x.CalculationSource.ToLower().Contains("reimbursement")).Sum(x => x.CalculatedAmount), g.Where(x => x.CalculationSource.ToLower().Contains("loan")).Sum(x => x.CalculatedAmount), g.Where(x => x.CalculationSource.ToLower().Contains("variable")).Sum(x => x.CalculatedAmount), g.Where(x => x.CalculationSource.ToLower().Contains("adjustment")).Sum(x => x.CalculatedAmount)), ct); }
    private async Task<Dictionary<Guid, (string Code, string Name)>> NamesAsync(bool department, IEnumerable<Guid> ids, CancellationToken ct) { var list = ids.Distinct().ToList(); if (department) return await db.Departments.AsNoTracking().Where(x => x.TenantId == tenant.TenantId && list.Contains(x.Id)).ToDictionaryAsync(x => x.Id, x => (x.Code, x.Name), ct); return await db.CostCenters.AsNoTracking().Where(x => x.TenantId == tenant.TenantId && list.Contains(x.Id)).ToDictionaryAsync(x => x.Id, x => (x.Code, x.Name), ct); }
    private static string Label(Guid? id, IReadOnlyDictionary<Guid, (string Code, string Name)> names) => id.HasValue && names.TryGetValue(id.Value, out var x) ? x.Code : "UNCLASSIFIED";
    private static decimal SumLine(IEnumerable<FinalSettlementLine> lines, FinalSettlementLineType type) => lines.Where(x => x.LineType == type && x.IsEarning).Sum(x => x.Amount);
    private static async Task<Result<PagedResult<T>>> PageAsync<T>(IQueryable<T> source, PayrollReportQuery q, CancellationToken ct) { var total = await source.CountAsync(ct); var rows = await source.Skip((q.Page - 1) * q.PageSize).Take(q.PageSize).ToListAsync(ct); return Result<PagedResult<T>>.Success(new(rows, q.Page, q.PageSize, total)); }
}
